#include <vector>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxDistinctPrimeCount(std::vector<int>& nums) {
        int n = nums.size();
        if (n < 2) return 0;
        int max_val = *std::max_element(nums.begin(), nums.end());
        std::vector<int> spf(max_val + 1);
        for (int i = 0; i <= max_val; ++i) spf[i] = i;
        for (int i = 2; i * i <= max_val; ++i) {
            if (spf[i] == i) {
                for (int j = i * i; j <= max_val; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }
        std::vector<std::unordered_set<int>> factors(n);
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                factors[i].insert(p);
                while (x % p == 0) x /= p;
            }
        }
        std::vector<int> pref_count(n), suff_count(n);
        std::unordered_set<int> run;
        for (int i = 0; i < n; ++i) {
            run.insert(factors[i].begin(), factors[i].end());
            pref_count[i] = run.size();
        }
        run.clear();
        for (int i = n - 1; i >= 0; --i) {
            run.insert(factors[i].begin(), factors[i].end());
            suff_count[i] = run.size();
        }
        int best = 0;
        for (int i = 0; i < n - 1; ++i) {
            best = std::max(best, pref_count[i] + suff_count[i + 1]);
        }
        return best;
    }
};

import java.util.*;

class Solution {
    public int maxDistinctPrimeCount(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;
        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;
        int[] spf = new int[maxVal + 1];
        for (int i = 0; i <= maxVal; i++) spf[i] = i;
        for (int i = 2; i * i <= maxVal; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }
        List<Set<Integer>> factors = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> set = new HashSet<>();
            int x = nums[i];
            while (x > 1) {
                int p = spf[x];
                set.add(p);
                while (x % p == 0) x /= p;
            }
            factors.add(set);
        }
        int[] prefCount = new int[n];
        int[] suffCount = new int[n];
        Set<Integer> run = new HashSet<>();
        for (int i = 0; i < n; i++) {
            run.addAll(factors.get(i));
            prefCount[i] = run.size();
        }
        run.clear();
        for (int i = n - 1; i >= 0; i--) {
            run.addAll(factors.get(i));
            suffCount[i] = run.size();
        }
        int best = 0;
        for (int i = 0; i < n - 1; i++) {
            best = Math.max(best, prefCount[i] + suffCount[i + 1]);
        }
        return best;
    }
}

