var maxDistinctPrimeCount = function(nums) {
    const n = nums.length;
    if (n < 2) return 0;
    const maxVal = Math.max(...nums);
    const spf = new Int32Array(maxVal + 1);
    for (let i = 0; i <= maxVal; i++) spf[i] = i;
    for (let i = 2; i * i <= maxVal; i++) {
        if (spf[i] === i) {
            for (let j = i * i; j <= maxVal; j += i) {
                if (spf[j] === j) spf[j] = i;
            }
        }
    }
    const factors = new Array(n);
    for (let i = 0; i < n; i++) {
        const s = new Set();
        let x = nums[i];
        while (x > 1) {
            const p = spf[x];
            s.add(p);
            while (x % p === 0) x = Math.floor(x / p);
        }
        factors[i] = s;
    }
    const prefCount = new Int32Array(n);
    const suffCount = new Int32Array(n);
    let run = new Set();
    for (let i = 0; i < n; i++) {
        for (const p of factors[i]) run.add(p);
        prefCount[i] = run.size;
    }
    run = new Set();
    for (let i = n - 1; i >= 0; i--) {
        for (const p of factors[i]) run.add(p);
        suffCount[i] = run.size;
    }
    let best = 0;
    for (let i = 0; i < n - 1; i++) {
        const total = prefCount[i] + suffCount[i + 1];
        if (total > best) best = total;
    }
    return best;
};
